    let HAZE = '#4a9cf0';    // couleur de brume des plantes d'arrière-plan (suit le fond choisi)
    const SPR = {};          // nom -> { c, f, w, h }
    const VARIANTS = {};     // 'kelp' -> ['kelp_0', 'kelp_1', ...]
    let atlasReady = false;

    let atlasImg = null;

    // Découpe l'atlas en sprites. Rejouable : les objets SPR sont mis à jour sur place,
    // ce qui permet de tout redessiner si le navigateur a vidé les canvas hors écran.
    function cutSprites() {
        for (const name in ATLAS.s) {
            const r = ATLAS.s[name];
            const c = mkCanvas(r[2], r[3]);
            c.getContext('2d', CTX_OPT).drawImage(atlasImg, r[0], r[1], r[2], r[3], 0, 0, r[2], r[3]);
            const f = mkCanvas(r[2], r[3]);
            const fx = f.getContext('2d', CTX_OPT);
            fx.translate(r[2], 0); fx.scale(-1, 1); fx.drawImage(c, 0, 0);
            if (SPR[name]) {
                const s = SPR[name];
                s.c = c; s.f = f; s.hazeC = null; s.hazeF = null; s.src32 = null; s.tent = null;
            } else {
                SPR[name] = { c, f, w: r[2], h: r[3] };
                const m = /^(.*)_(\d+)$/.exec(name);
                const base = m ? m[1] : name;
                (VARIANTS[base] = VARIANTS[base] || []).push(name);
            }
        }
    }

    function loadAtlas(done) {
        const img = new Image();
        img.onload = () => {
            atlasImg = img;
            cutSprites();
            atlasReady = true;
            done();
        };
        img.onerror = () => console.error('[Pixel Aquarium] atlas illisible');
        img.src = ATLAS.img;
    }

    // Vrai si un canvas hors écran a été vidé (perte du contexte graphique).
    function canvasLost(cv, x, y) {
        try { return cv.getContext('2d', CTX_OPT).getImageData(x, y, 1, 1).data[3] === 0; }
        catch (e) { return true; }
    }

    // Copie "dans la brume" d'un sprite, pour les plantes d'arrière-plan.
    function hazed(s, flip) {
        const key = flip ? 'hazeF' : 'hazeC';
        if (!s[key]) {
            const c = mkCanvas(s.w, s.h), x = c.getContext('2d', CTX_OPT);
            x.drawImage(flip ? s.f : s.c, 0, 0);
            x.globalCompositeOperation = 'source-atop';
            x.fillStyle = HAZE; x.globalAlpha = 0.42;
            x.fillRect(0, 0, s.w, s.h);
            s[key] = c;
        }
        return s[key];
    }

